'use strict';

// MODULES //

var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Parses a JSON Pointer string into an array of reference tokens.
*
* ## Notes
*
* -   Implements parsing per RFC 6901.
* -   An empty string returns an empty array (refers to the root of the document).
* -   Escape sequences are decoded: `~1` is unescaped to `/` before `~0` is unescaped to `~`.
*
* @param {string} pointer - JSON Pointer string
* @throws {TypeError} must provide a string
* @throws {Error} pointer must be empty or start with a `/` character
* @returns {Array<string>} array of unescaped reference tokens
*
* @example
* var tokens = parse( '/foo/bar' );
* // returns [ 'foo', 'bar' ]
*
* @example
* var tokens = parse( '/a~1b/c~0d' );
* // returns [ 'a/b', 'c~d' ]
*
* @example
* var tokens = parse( '' );
* // returns []
*/
function parse( pointer ) {
	var tokens;
	var i;

	if ( !isString( pointer ) ) {
		throw new TypeError( format( 'invalid argument. Must provide a string. Value: `%s`.', pointer ) );
	}
	// An empty string refers to the root of the document:
	if ( pointer === '' ) {
		return [];
	}
	// Per RFC 6901, a non-empty pointer MUST begin with '/':
	if ( pointer.charAt( 0 ) !== '/' ) {
		throw new Error( format( 'invalid argument. JSON Pointer must be an empty string or start with a `/` character. Value: `%s`.', pointer ) );
	}

	tokens = pointer.split( '/' );
	tokens = tokens.slice( 1 );

	// Unescape reference tokens per RFC 6901 (note: '~1' must be replaced before '~0' to avoid corrupting sequences such as '~01'):
	for ( i = 0; i < tokens.length; i++ ) {
		tokens[ i ] = tokens[ i ].replace( /~1/g, '/' );
		tokens[ i ] = tokens[ i ].replace( /~0/g, '~' );
	}
	return tokens;
}


// EXPORTS //

module.exports = parse;
